# Reduced snapshot of the historical scripts/test-runner.cjs.
const { spawnSync } = require("node:child_process");

function childEnv(extra) {
  return { ...process.env, ...extra };
}

function runFile(file) {
  return spawnSync(process.execPath, ["--test", file], { env: childEnv() });
}
